import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.Cq50P25D.js";var i=JSON.parse(`{"title":"Contribute to Sync Engine","description":"","frontmatter":{},"headers":[],"relativePath":"usage/contributing.md","filePath":"en/usage/contributing.md","lastUpdated":1785588746000}`),a={name:`usage/contributing.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="contribute-to-sync-engine" tabindex="-1">Contribute to Sync Engine <a class="header-anchor" href="#contribute-to-sync-engine" aria-label="Permalink to “Contribute to Sync Engine”">​</a></h1><p>Sync Engine welcomes any contribution to the plugin core, modules, and documentation, as well as issues and feature requests.</p><h2 id="issue-policy" tabindex="-1">Issue Policy <a class="header-anchor" href="#issue-policy" aria-label="Permalink to “Issue Policy”">​</a></h2><p>The Sync Engine repository accepts two kinds of issues - bug report and feature request.</p><h3 id="bug-report" tabindex="-1">Bug Report <a class="header-anchor" href="#bug-report" aria-label="Permalink to “Bug Report”">​</a></h3><p><strong>For a bug report, the issue must contain</strong>:</p><ul><li>Clear description and reproduction steps</li><li>The list of all modules you are using</li><li>The storage service you are using</li><li>For bugs during syncing, please provide the logs, exported from <code>Development</code> settings</li></ul><p><strong>It must not contain</strong>:</p><ul><li>Any sensitive information about yourself</li><li>More than one bug - please report in separate issues</li></ul><p>Issues where maintainers have requested clarification / coordinated testing but the reporter hasn&#39;t provided any relevant information will be closed after 72 hours.</p><h3 id="feature-request" tabindex="-1">Feature Request <a class="header-anchor" href="#feature-request" aria-label="Permalink to “Feature Request”">​</a></h3><p><strong>A feature request contains</strong>:</p><ul><li>Clear description of now the feature should work</li><li>(Optional) Your idea of implementation of you would like to participate the brainstorming</li></ul><p>A feature request is a normal issue, but maintainers will move the request to a dedicated meta issue for easier management after some communication.</p><p>We <strong>strongly recommend</strong> you writing your own Sync Engine module to achieve your requirement before opening a feature request, since Sync Engine is super extensible and most functions can be achieved by modules. Sync Engine also provides official SDK, documentation, and AI agent skill to assist module development. There are abundant module examples in the Sync Engine monorepo.</p><h2 id="fork-policy" tabindex="-1">Fork Policy <a class="header-anchor" href="#fork-policy" aria-label="Permalink to “Fork Policy”">​</a></h2><p>Sync Engine welcomes forks that contributes to the development of the Sync Engine monorepo.</p><p>However, as stated in <a href="https://docs.obsidian.md/Developer+policies#Forks" target="_blank" rel="noreferrer">Obsidian developer policies</a>, Sync Engine disallows any type if malicious forking that submits to Obsidian&#39;s official plugin directory as another standalone plugin, as long as Sync Engine repo remains active or maintainers haven&#39;t permitted. Maintainers will report as long as we find one.</p><p>Instead of creating another syncing plugin, we highly recommend you to create a Sync Engine module. Sync Engine core is highly optimized and battle-tested, it provides convenient SDK that allows you to customize freely without reinventing the wheel.</p><h2 id="contribute-code-to-the-monorepo" tabindex="-1">Contribute Code to the Monorepo <a class="header-anchor" href="#contribute-code-to-the-monorepo" aria-label="Permalink to “Contribute Code to the Monorepo”">​</a></h2><h3 id="how-the-monorepo-works" tabindex="-1">How the Monorepo Works <a class="header-anchor" href="#how-the-monorepo-works" aria-label="Permalink to “How the Monorepo Works”">​</a></h3><p><strong>Techstack</strong>:</p><p>The project uses:</p><ul><li><strong>TypeScript 7</strong> as programming language</li><li><strong>Bun</strong> as its package manager and task runner</li><li><strong>Turbo</strong> for monorepo management</li><li><strong>Tsdown</strong> for building</li><li><strong>Oxlint and Oxfmt</strong> for linting and formatting</li><li><strong>VitePress</strong> for documentation website</li></ul><p>The plugin core uses:</p><ul><li><strong>Solid.js</strong> and <strong>TailwindCSS</strong> (via UnoCSS) for UI</li><li>custom package <strong>SynthKernel</strong> for dependency injection</li><li>custom package <strong>Uni-KV</strong> for IndexedDB and in-memory database.</li></ul><p><strong>Monorepo structure</strong>:</p><div class="language-txt"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sync Engine Monorepo</span></span>
<span class="line"><span>├── docs          - Documentation website</span></span>
<span class="line"><span>├── blueprint     - Internal mechanisms</span></span>
<span class="line"><span>├── packages</span></span>
<span class="line"><span>│   ├── plugin    - Core plugin and SDK (@hesprs/sync-engine-sdk)</span></span>
<span class="line"><span>│   ├── shared    - Shared utilities (@repo/shared)</span></span>
<span class="line"><span>│   └── ...       - Others are all official modules</span></span>
<span class="line"><span>├── modules.json  - Official module source, records all official modules</span></span>
<span class="line"><span>└── tsconfig.json - TypeScript config for all packages</span></span></code></pre></div><p><strong>Commands</strong>:</p><table tabindex="0"><thead><tr><th>Command</th><th>Usage</th></tr></thead><tbody><tr><td><code>bun dev</code></td><td>Build without clearing dist folder</td></tr><tr><td><code>bun compile</code></td><td>Build with clearing</td></tr><tr><td><code>bun dev:plugin</code></td><td>Build the plugin without cleaning dist</td></tr><tr><td><code>bun build:plugin</code></td><td>Build the plugin with clearing</td></tr><tr><td><code>bun fix</code></td><td>Format and fix fixable lint errors</td></tr><tr><td><code>bun check</code></td><td>Check types, lint and format</td></tr><tr><td><code>bun tests</code></td><td>Run all tests</td></tr><tr><td><code>bun &lt;command&gt; -F &lt;package-name&gt;</code></td><td>Run command targeting one package</td></tr></tbody></table><p><strong>CI/CD</strong>:</p><p>The CI is run for every pull request commits, it runs <code>bun check</code> and <code>bun tests</code>. If any of them fails, the pull request cannot merge.</p><p>The core plugin release is triggered by any tag push. Tags containing hyphens trigger pre-release, tags with no hyphens trigger normal release. The release workflow captures corresponding description in <code>packages/plugin/CHANGELOG.md</code> as release detail.</p><p>The module binaries are distributed in GitHub Pages (Why? better CDN and fewer rate limits) alongside the documentation website. When documentation directory or <code>modules.json</code> changes are pushed to main branch, the deployment runs automatically.</p><p>The SDK package is released to npm, version aligned with the plugin. The release relies on manual workflow trigger.</p><h3 id="open-a-pull-request" tabindex="-1">Open a Pull Request <a class="header-anchor" href="#open-a-pull-request" aria-label="Permalink to “Open a Pull Request”">​</a></h3><p>You can open a pull request for debugging or new features. For bug-fix pull requests, the request must reference at least one open issue.</p><p>Commit message format: <code>&lt;title&gt;(&lt;scope&gt;): &lt;message&gt;</code>. Keep the message concise, avoid lengthy &quot;files changed&quot; or ASCII arts.</p><p>It is required to document relevant implementation in <code>docs</code> directory if your contribution creates a new module, contains sophisticated implementations, or changes core SDK API.</p><p>For maintainer convenience, the review messages will be in English. Same to issues, if a pull request failed review or CI and hasn&#39;t had any meaningful changes over 72 hours, the PR will be closed.</p><h4 id="module-contribution" tabindex="-1">Module Contribution <a class="header-anchor" href="#module-contribution" aria-label="Permalink to “Module Contribution”">​</a></h4><p>If you want to contribute a new module, please make it a package under <code>packages</code>. The <code>package.json</code> of your module should at least include the following:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;contributors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;the-name-to-call-you&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;github&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;your-github-account-name&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Then modify <code>modules.json</code> at the repo root to include your module:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Module Name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-module&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;icon&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;puzzle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Description for your module&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://sync.consensia.cc/modules/module-name.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Once the PR is accepted, you module will become part of official modules. You will also be responsible for the future issues and pull requests about your module.</p><p>If your pull request contains substantial modification of an existing module, you can also include your information in the <code>contributors</code> field.</p><h4 id="ai-contribution" tabindex="-1">AI Contribution <a class="header-anchor" href="#ai-contribution" aria-label="Permalink to “AI Contribution”">​</a></h4><p>Sync Engine repo generally accepts AI contribution, especially for modules, as long as it:</p><ul><li>Passes CI</li><li>Passes review</li><li>Has code quality acceptable by maintainers</li><li>Can keep responsible to future maintenance</li></ul><p>The code can be written by AI, but when making pull requests, Sync Engine requires the author must be the GitHub account of a real human. <strong>Any names of AI agent entities are forbidden in co-author list, commit messages, and code.</strong> This is because:</p><ul><li>Commits made by AI often signify insufficient development skill of the human to be capable for future maintenance.</li><li>Copyright of code in this repo belong to the corresponding authors and contributors, AI co-authoring creates ambiguities around code ownership.</li></ul>`,52)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};